<template><article class="card announcement" @click="$emit('open',announcement.id)"><div><el-tag v-if="announcement.top" type="danger" size="small">置顶</el-tag> <el-tag size="small">{{announcement.category}}</el-tag> <el-tag size="small" type="warning">{{scopeText(announcement)}}</el-tag><h3>{{announcement.title}}</h3><p>{{announcement.content}}</p></div><div class="announcement-meta"><template v-if="isStaff"><small v-if="announcement.category==='紧急'">已确认 {{announcement.confirmed_count}} 人 · 未确认 {{announcement.unconfirmed_users?.length||0}} 人</small><small v-else>已读 {{announcement.read_count}}</small></template><template v-else><small v-if="announcement.category==='紧急'"><el-tag v-if="announcement.confirmed" type="success" size="small">已确认</el-tag><el-tag v-else type="danger" size="small">待确认</el-tag></small><small v-else>已读 {{announcement.read_count}}</small></template></div></article></template><script setup lang="ts">import{computed}from'vue';import type{Announcement}from'../../types';import{authStore}from'../../stores/authStore';defineProps<{announcement:Announcement}>();defineEmits<{open:[id:number]}>();const isStaff=computed(()=>['staff','admin'].includes(authStore.user?.role||''));function scopeText(a:Announcement){if(a.scope==='building')return`楼栋 · ${a.scope_building}`;if(a.scope==='unit')return`单元 · ${a.scope_building} ${a.scope_unit}`;return'全小区';}</script>
